n=16
cand6=[[7]*n for _ in range(n)]
segs=[(8,7,0,3),(8,11,2,2),(1,15,4,6),(4,19,6,9),(4,23,8,4)]
target=6
for col,s,start,length in segs:
    end=start+length-1
    newstart=end-target+1
    if newstart < 0 or s-newstart >= n:
        # keep in-bounds, extend at the lower-left end
        newstart=start
        for r in range(start,start+target):
            if 0<=r<n and 0<=s-r<n: cand6[r][s-r]=col
    else:
        for r in range(newstart,end+1):
            if 0<=r<n and 0<=s-r<n: cand6[r][s-r]=col
print('\n'.join(' '.join(map(str,row)) for row in cand6))
